<div class="live-room" id="room" data-user="{{ auth()->id() }}" data-instructor="{{ $session->course->instructor_id }}" data-csrf="{{ csrf_token() }}" data-presence="{{ route('sessions.presence',$session) }}" data-signals="{{ route('sessions.signals',$session) }}" data-send="{{ route('sessions.signals.send',$session) }}" data-recording="{{ route('sessions.recording',$session) }}" data-attendance-status="{{ route('sessions.attendance-status',$session) }}" data-complete="{{ route('sessions.complete',$session) }}">
<header class="live-header"><div><span class="live-kicker">{{ $en ? 'IN-PORTAL LIVE CLASS' : 'PORTAL İÇİ CANLI SINIF' }}</span><h1>{{ $session->title }}</h1><p>{{ $session->course->title }} · {{ $session->starts_at?->format('d.m.Y H:i') }}</p></div><div class="live-status"><i></i><span id="roomStatus">{{ $en ? 'Waiting for connection' : 'Bağlantı bekleniyor' }}</span></div></header>
<div class="live-layout"><main class="live-main"><div class="video-stage" id="videos"><div class="video-tile local-tile" id="localTile" style="display:none"><video id="localVideo" autoplay muted playsinline></video><div class="tile-footer"><span class="tile-avatar">{{ mb_strtoupper(mb_substr(auth()->user()->name,0,1)) }}</span><span>{{ auth()->user()->name }} <em>{{ $en ? 'Me' : 'Ben' }}</em></span><b id="localMic">🎙</b></div></div><div class="empty-stage" id="emptyStage"><span>◉</span><strong>{{ $en ? 'Ready to join the class?' : 'Sınıfa katılmaya hazır mısınız?' }}</strong><small>{{ $en ? 'Turn on your camera and microphone to join the session.' : 'Kamera ve mikrofonunuzu açarak derse katılın.' }}</small><div class="pre-join-toggles"><label><input type="checkbox" id="wantVideo" checked> {{ $en ? 'Camera' : 'Kamera' }}</label><label><input type="checkbox" id="wantAudio" checked> {{ $en ? 'Microphone' : 'Mikrofon' }}</label></div><p class="join-error" id="joinError" style="display:none"></p></div></div><div class="control-bar"><button class="control primary" id="join">🎥 <span>{{ $en ? 'Join' : 'Katıl' }}</span></button><button class="control" id="mute" disabled>🎙 <span>{{ $en ? 'Microphone' : 'Mikrofon' }}</span></button><button class="control" id="camera" disabled>▣ <span>{{ $en ? 'Camera' : 'Kamera' }}</span></button><button class="control" id="screen" disabled>▤ <span>{{ $en ? 'Share screen' : 'Ekran paylaş' }}</span></button>@if(auth()->id()===$session->course->instructor_id)<button class="control record" id="record" disabled>● <span>{{ $en ? 'Start recording' : 'Kaydı başlat' }}</span></button>@endif@if(auth()->id()!==$session->course->instructor_id && $session->meeting_status!=='not_applicable')<button class="control" id="completeSession" disabled title="{{ $en ? 'Enabled once you have stayed in the room long enough' : 'Yeterli süre odada kaldığınızda etkinleşir' }}">✓ <span>{{ $en ? 'Complete session' : 'Dersi tamamla' }}</span></button>@endif<button class="control leave" id="leave" disabled>↪ <span>{{ $en ? 'Leave' : 'Çıkış' }}</span></button></div></main><aside class="live-sidebar"><section class="panel participants-panel"><div class="panel-title"><h2>{{ $en ? 'Participants' : 'Katılımcılar' }}</h2><span id="participantCount">1</span></div><div id="participants" class="participant-list"><div class="participant"><span class="participant-avatar">{{ mb_strtoupper(mb_substr(auth()->user()->name,0,1)) }}</span><div><strong>{{ auth()->user()->name }}</strong><small>{{ auth()->id()===$session->course->instructor_id ? ($en ? 'Instructor' : 'Eğitmen') : ($en ? 'Participant' : 'Katılımcı') }}</small></div><b>🎙</b></div></div></section><section class="panel chat-panel"><div class="panel-title"><h2>{{ $en ? 'Class chat' : 'Sınıf sohbeti' }}</h2><span>💬</span></div><div class="chat-log" id="chat">@foreach($messages as $message)<div class="chat-message"><strong>{{ $message->user->name }}</strong><p>{{ $message->body }}</p></div>@endforeach</div><form class="chat-form" method="post" action="{{ route('sessions.messages',$session) }}">@csrf<input name="body" placeholder="{{ $en ? 'Write a message...' : 'Mesaj yazın...' }}" required><button type="submit">↑</button></form></section><section class="panel files-panel"><div class="panel-title"><h2>{{ $en ? 'Shared files' : 'Paylaşılan dosyalar' }}</h2><span>⌕</span></div><p class="panel-empty">{{ $en ? 'No files have been shared in this session yet.' : 'Bu oturumda henüz dosya paylaşılmadı.' }}</p></section></aside></div></div>
<script>
const root=document.getElementById('room'),me=Number(root.dataset.user),instructor=Number(root.dataset.instructor),csrf=root.dataset.csrf;let stream=null,peers={},recorder=null,chunks=[],polling=false;
const i18n={
    participant: {{ \Illuminate\Support\Js::from($en ? 'Participant' : 'Katılımcı') }},
    instructor: {{ \Illuminate\Support\Js::from($en ? 'Instructor' : 'Eğitmen') }},
    connected: {{ \Illuminate\Support\Js::from($en ? 'Connected to class' : 'Sınıfa bağlanıldı') }},
    joinNoDevice: {{ \Illuminate\Support\Js::from($en ? 'You must leave at least your camera or microphone on to join.' : 'Katılmak için kamera veya mikrofondan en az birini açık bırakmalısınız.') }},
    errNotAllowed: {{ \Illuminate\Support\Js::from($en ? 'Camera/microphone permission was denied. Allow it from the lock icon in your browser address bar and try again.' : 'Kamera/mikrofon izni reddedildi. Tarayıcı adres çubuğundaki kilit simgesinden izin verip tekrar deneyin.') }},
    errNotFound: {{ \Illuminate\Support\Js::from($en ? 'No camera or microphone found. Check your device and try again.' : 'Kamera veya mikrofon bulunamadı. Cihazınızı kontrol edip tekrar deneyin.') }},
    errNotReadable: {{ \Illuminate\Support\Js::from($en ? 'Your camera or microphone is being used by another application. Close other apps and try again.' : 'Kamera veya mikrofona başka bir uygulama tarafından erişiliyor. Diğer uygulamaları kapatıp tekrar deneyin.') }},
    errGeneric: {{ \Illuminate\Support\Js::from($en ? 'Could not access camera/microphone: ' : 'Kameraya/mikrofona erişilemedi: ') }},
    canComplete: {{ \Illuminate\Support\Js::from($en ? 'Session can be completed' : 'Ders tamamlanabilir') }},
    remaining: {{ \Illuminate\Support\Js::from($en ? 'Time remaining: ' : 'Kalan süre: ') }},
    seconds: {{ \Illuminate\Support\Js::from($en ? 's' : 'sn') }},
    sessionCompleted: {{ \Illuminate\Support\Js::from($en ? 'Session marked as completed' : 'Ders tamamlandı olarak işaretlendi') }},
    recordingUploaded: {{ \Illuminate\Support\Js::from($en ? 'Recording uploaded to the server' : 'Kayıt sunucuya aktarıldı') }},
    stopRecording: {{ \Illuminate\Support\Js::from($en ? 'Stop recording' : 'Kaydı durdur') }},
    startRecording: {{ \Illuminate\Support\Js::from($en ? 'Start recording' : 'Kaydı başlat') }}
};
const send=async(type,payload,recipient_id=null)=>fetch(root.dataset.send,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({type,payload,recipient_id})});
function setStatus(t){document.getElementById('roomStatus').textContent=t}
function addRemote(id,name){let tile=document.getElementById('tile-'+id);if(!tile){tile=document.createElement('div');tile.className='video-tile';tile.id='tile-'+id;tile.innerHTML='<video autoplay playsinline></video><div class="tile-footer"><span class="tile-avatar">'+name.slice(0,1).toUpperCase()+'</span><span>'+name+'</span><b>🎙</b></div>';document.getElementById('videos').prepend(tile)}return tile.querySelector('video')}
function peer(id,name,initiator){if(peers[id])return peers[id];let pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});peers[id]=pc;if(stream)stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.ontrack=e=>addRemote(id,name).srcObject=e.streams[0];pc.onicecandidate=e=>e.candidate&&send('candidate',e.candidate,id);pc.onconnectionstatechange=()=>{if(['failed','disconnected','closed'].includes(pc.connectionState)){document.getElementById('tile-'+id)?.remove();delete peers[id]}};if(initiator)pc.createOffer().then(o=>pc.setLocalDescription(o).then(()=>send('offer',o,id)));return pc}
async function heartbeat(){if(!stream)return;await fetch(root.dataset.presence,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}});let users=await(await fetch(root.dataset.presence,{headers:{'Accept':'application/json'}})).json();let list=document.getElementById('participants');list.innerHTML='';users.forEach(u=>{let row=document.createElement('div');row.className='participant';row.innerHTML='<span class="participant-avatar">'+u.name.slice(0,1).toUpperCase()+'</span><div><strong>'+u.name+'</strong><small>'+(u.id===instructor?i18n.instructor:i18n.participant)+'</small></div><b>🎙</b>';list.append(row);if(u.id!==me)peer(u.id,u.name,instructor===me)});document.getElementById('participantCount').textContent=users.length;setTimeout(heartbeat,5000)}
async function poll(){if(!stream)return;let data=await(await fetch(root.dataset.signals,{headers:{'Accept':'application/json'}})).json();for(const s of data){let p=peers[s.sender_id]||peer(s.sender_id,i18n.participant,false),payload=JSON.parse(s.payload);if(s.type==='offer'){await p.setRemoteDescription(payload);let answer=await p.createAnswer();await p.setLocalDescription(answer);await send('answer',answer,s.sender_id)}else if(s.type==='answer')await p.setRemoteDescription(payload);else if(s.type==='candidate')try{await p.addIceCandidate(payload)}catch(e){}}setTimeout(poll,1000)}
async function checkAttendance(){if(!stream||!root.dataset.attendanceStatus)return;let data=await(await fetch(root.dataset.attendanceStatus,{headers:{'Accept':'application/json'}})).json();let btn=document.getElementById('completeSession');if(btn){btn.disabled=!data.eligible;btn.title=data.eligible?i18n.canComplete:i18n.remaining+Math.max(0,data.required_seconds-data.attended_seconds)+' '+i18n.seconds}setTimeout(checkAttendance,5000)}
function showJoinError(msg){let el=document.getElementById('joinError');if(el){el.textContent=msg;el.style.display='block'}}
async function join(){
if(stream)return;
const joinBtn=document.getElementById('join'),errorEl=document.getElementById('joinError');
const wantVideo=document.getElementById('wantVideo')?.checked??true,wantAudio=document.getElementById('wantAudio')?.checked??true;
if(errorEl)errorEl.style.display='none';
if(!wantVideo&&!wantAudio){showJoinError(i18n.joinNoDevice);return}
joinBtn.disabled=true;
try{
stream=await navigator.mediaDevices.getUserMedia({video:wantVideo,audio:wantAudio});
}catch(err){
joinBtn.disabled=false;
const messages={NotAllowedError:i18n.errNotAllowed,NotFoundError:i18n.errNotFound,NotReadableError:i18n.errNotReadable};
showJoinError(messages[err.name]||(i18n.errGeneric+err.message));
return;
}
document.getElementById('localVideo').srcObject=stream;
document.getElementById('localTile').style.display='';
document.getElementById('emptyStage').remove();
document.querySelectorAll('.control:not(#join)').forEach(b=>b.disabled=false);
if(!stream.getVideoTracks().length)document.getElementById('camera').disabled=true;
if(!stream.getAudioTracks().length)document.getElementById('mute').disabled=true;
document.getElementById('completeSession')&&(document.getElementById('completeSession').disabled=true);
joinBtn.disabled=true;
setStatus(i18n.connected);
heartbeat();poll();checkAttendance();
}
document.getElementById('join').onclick=join;document.getElementById('mute').onclick=()=>{let t=stream?.getAudioTracks()[0];if(t){t.enabled=!t.enabled;document.getElementById('mute').classList.toggle('is-off',!t.enabled);document.getElementById('localMic').textContent=t.enabled?'🎙':'🔇'}};document.getElementById('camera').onclick=()=>{let t=stream?.getVideoTracks()[0];if(t){t.enabled=!t.enabled;document.getElementById('camera').classList.toggle('is-off',!t.enabled)}};document.getElementById('screen').onclick=async()=>{if(!stream){await join();if(!stream)return}let s=await navigator.mediaDevices.getDisplayMedia({video:true}),sender=Object.values(peers).flatMap(p=>p.getSenders()).find(x=>x.track?.kind==='video');if(sender)sender.replaceTrack(s.getVideoTracks()[0]);document.getElementById('localVideo').srcObject=s;s.getVideoTracks()[0].onended=()=>document.getElementById('localVideo').srcObject=stream};document.getElementById('leave').onclick=()=>{stream?.getTracks().forEach(t=>t.stop());location.href='{{ route('learning.index') }}'};
document.getElementById('completeSession')?.addEventListener('click',async()=>{let r=await fetch(root.dataset.complete,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}});if(r.ok||r.redirected){setStatus(i18n.sessionCompleted);document.getElementById('completeSession').disabled=true}});document.getElementById('record')?.addEventListener('click',async e=>{if(!recorder){if(!stream){await join();if(!stream)return}chunks=[];recorder=new MediaRecorder(stream,{mimeType:'video/webm'});recorder.ondataavailable=x=>x.data.size&&chunks.push(x.data);recorder.onstop=async()=>{let fd=new FormData();fd.append('recording',new File([new Blob(chunks,{type:'video/webm'})],'session-recording.webm',{type:'video/webm'}));await fetch(root.dataset.recording,{method:'POST',headers:{'X-CSRF-TOKEN':csrf},body:fd});setStatus(i18n.recordingUploaded)};recorder.start();e.currentTarget.querySelector('span').textContent=i18n.stopRecording}else{recorder.stop();recorder=null;e.currentTarget.querySelector('span').textContent=i18n.startRecording}});
</script>
@endsection
